const Small = Int where self >= 0 && self < 100;
const Positive = Int where self > 0;

let increment :: Small -> Positive = fn value => value + 1;
let getX :: { .x: Small; } -> Small = fn record => record.x;

return increment (getX { .x = 41; .name = "example"; });

const Small = Int where self >= 0 && self < 100;
const Positive = Int where self > 0;

let increment :: Small -> Positive = fn value => value + 1;
// The explicit contract preserves the scalar bound across this call.
let getX :: { .x: Small; } -> Small = fn record => record.x;
return increment (getX { .x = 41; .name = "example"; });

let compose = fn f => fn g => fn value => f (g value);
let increment = fn value => value + 1;
let twice = compose increment increment;
let values = map twice [1, 2, 3];
return fold (fn total => fn value => total + value) 0 values;

const Positive = Int where self > 0;
let keepPositive :: Int -> Int = fn value =>
    if value > 0 then do {
        let checked :: Positive = value;
        return checked;
    } else 0;
return map keepPositive [-2, 0, 42];

let getX = fn record => record.x;
let move = fn delta => fn entity => {
    .position = getX entity + delta;
    .name = entity.name;
};
let entities = [
    { .x = 10; .name = "first"; },
    { .x = 20; .name = "second"; }
];
return map (move 3) entities;
